8	
9	// 本文件回归保障除外故障代码清单的数据隔离：产品一经登记，保修规则以登记
10	// 当时的清单快照为准；调用方随后修改自己持有的登记入参或取回的产品资料，
11	// 都不能改变已登记产品的资格判断与备件预留结果。包不提供修改保修条款的
12	// 操作，这些测试只沿用登记、取回、查询与预留等既有公开行为。
13	
14	// isolationStore 构造一个产品（除外 BROKEN_SEAL）、库存 10 的备件和若干请求。
15	func isolationStore(t *testing.T, excluded []string) *Store {
16		t.Helper()
17		s := NewStore()
18		if err := s.RegisterProduct("p1", t0, 30, excluded); err != nil {
19			t.Fatalf("register product: %v", err)
20		}
21		if err := s.RegisterPart("part1", 10); err != nil {
22			t.Fatalf("register part: %v", err)
